var t=`0519-fesenjan`;var i=`world-0519`;var o=`IR`;var a=`western-asia`;var r=4;var s=132;var l={en:`Fesenjan`,ua:`Фесенджан`};var u={en:`A traditional dish from Iran, centered on walnut, yellow onion, chicken thigh, basmati rice. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Іран. Основні складники: волоський горіх, жовта цибуля, куряче стегно, рис басматі. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Grind walnuts very finely, toast briefly with the onions, then loosen with water into a thick sauce.`,ua:`Дрібно змеліть горіхи, коротко прогрійте з цибулею, а потім додайте воду до густого соусу.`,t:[`chopping`,`sauteing`],m:12,i:[[`walnut`,330,`g`],[`yellow-onion`,160,`g`],[`unsalted-butter`,45,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 95 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 95 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:95,i:[[`chicken-thigh`,780,`g`],[`pomegranate-molasses`,190,`ml`],[`water`,550,`ml`],[`white-granulated-sugar`,30,`g`],[`ground-cinnamon`,3,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 25 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 25 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`basmati-rice`,390,`g`]]}];var d={slug:t,id:i,country:`IR`,region:a,servings:4,minutes:132,title:l,text:u,steps:g};export{o as country,d as default,i as id,s as minutes,a as region,r as servings,t as slug,g as steps,u as text,l as title};